// City type definitions
const CITY_TYPES = {
  homeRule: { label:'Home Rule Charter City', description:'Cities with population over 5,000 may adopt their own charter under Texas Local Government Code § 9.001. They have broad authority to govern local affairs not inconsistent with state law.' },
  generalLaw: { label:'General Law City', description:'Cities that operate under state law frameworks (Type A, B, or C) without a locally adopted charter. Authority limited to powers expressly granted by the Legislature.' },
  countyLaw: { label:'County Government', description:'Governed by Texas county government law. County commissioners court is the governing body.' }
};

// Key Texas laws applicable to all jurisdictions
const UNIVERSAL_TEXAS_LAWS = [
  { code:'TPC § 1.07', title:'Definitions', layman:'Defines key legal terms used throughout the Penal Code. Officers need to know these to properly identify offenses.' },
  { code:'TPC § 2.01', title:'Proof Beyond Reasonable Doubt', layman:'The prosecution must prove every element of the offense. If there is reasonable doubt, the defendant must be acquitted.' },
  { code:'TPC § 9.31', title:'Self-Defense', layman:'A person may use force to protect themselves when they reasonably believe it is immediately necessary.' },
  { code:'TPC § 9.32', title:'Deadly Force in Defense of Person', layman:'Deadly force is justified when a person reasonably believes they face an imminent risk of death, serious bodily injury, kidnapping, sexual assault, or robbery.' },
  { code:'TPC § 9.51', title:'Protection of Life or Health — Peace Officers', layman:'Officers may use force to effect an arrest or prevent escape. Deadly force is allowed only if the suspect poses a risk of death/serious injury to others.' },
  { code:'CCP Art. 14.01', title:'Offense Within View', layman:'Officers can arrest without a warrant if a crime is committed in their presence or view.' },
  { code:'CCP Art. 14.03', title:'Authority of Peace Officers', layman:'Officers can arrest a person in a suspicious place or under suspicious circumstances that lead to a belief a felony has been or will be committed.' },
  { code:'CCP Art. 15.17', title:'Duties of Arresting Officer', layman:'After arrest, the officer must take the accused before a magistrate within 48 hours for warnings and setting of bail.' },
  { code:'CCP Art. 38.22', title:'When Statements May Be Used', layman:'Confessions and admissions can only be used in court if proper Miranda-style warnings were given AND the person voluntarily waived those rights.' },
  { code:'Texas Const. Art. I § 9', title:'Unreasonable Search and Seizure', layman:'The Texas Constitution provides stronger protections against unreasonable search and seizure than even the U.S. Constitution\'s 4th Amendment.' },
];

// Get county by name
function getCountyByName(name) {
  return TEXAS_COUNTIES.find(c => c.name.toLowerCase() === name.toLowerCase());
}

// Get counties by region
function getCountiesByRegion(region) {
  return TEXAS_COUNTIES.filter(c => c.region === region);
}

// Search counties
function searchCounties(query) {
  const q = query.toLowerCase();
  return TEXAS_COUNTIES.filter(c =>
    c.name.toLowerCase().includes(q) ||
    c.seat.toLowerCase().includes(q) ||
    c.cities.some(ci => ci.toLowerCase().includes(q))
  );
}
